import{_ as a,a as i,b as o}from"./chunks/save_icon.CpA8n_KO.js";import{_ as n}from"./chunks/quick_control_icon.Cc9UwUrp.js";import{_ as t}from"./chunks/add_icon.D_Q72d6b.js";import{_ as r,o as c,c as s,a6 as d}from"./chunks/framework.mtgKxyez.js";const v=JSON.parse('{"title":"5. Software Basics","description":"","frontmatter":{},"headers":[],"relativePath":"en/basic/5.md","filePath":"en/basic/5.md"}'),l={name:"en/basic/5.md"};function h(p,e,u,m,g,b){return c(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="_5-software-basics" tabindex="-1">5. Software Basics <a class="header-anchor" href="#_5-software-basics" aria-label="Permalink to &quot;5. Software Basics&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Writing a project is basically graphical flowchart editing. First click a flow node, then drag other flow nodes from the left side into the project, or press certain robot arm buttons to create nodes. The new node is automatically connected below the selected node. You can also click the <code>×</code> under a node to disconnect the next node, or manually drag a connection line to connect two nodes.</p><h2 id="coordinate-systems-base" tabindex="-1">Coordinate Systems (Base) <a class="header-anchor" href="#coordinate-systems-base" aria-label="Permalink to &quot;Coordinate Systems (Base)&quot;">​</a></h2><p>The commonly used coordinate systems are:</p><ul><li>Robot Base: has an &quot;absolute position&quot; concept. Its coordinates always represent the same place.</li><li>Vision Base: has a &quot;relative position&quot; concept. It is automatically created after each vision task and its origin changes according to the detected object.</li><li>Tool coordinate system: usually only used with <code>Move</code>. Its origin is the flange center, so normally its Z axis is opposite to Robot Base. You cannot create this coordinate system separately from the project page.</li></ul><p>To change the coordinate system you are using, just use the dropdown menu in the upper-right corner.</p><p><img src="'+a+'" alt="Common coordinate systems"></p><blockquote><p>Common coordinate systems. The normal coordinate system in the middle is outside this textbook&#39;s scope.</p></blockquote><h2 id="moving-the-arm" tabindex="-1">Moving the Arm <a class="header-anchor" href="#moving-the-arm" aria-label="Permalink to &quot;Moving the Arm&quot;">​</a></h2><p>Hold the <code>FREE</code> button on the robot arm, then pull the arm directly to the position you want.</p><p>For finer movement, click <img src="'+n+'" alt="Quick Control icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> at the top and use <code>+</code> and <code>-</code> on the controller for small adjustments.</p><h2 id="point" tabindex="-1">Point <a class="header-anchor" href="#point" aria-label="Permalink to &quot;Point&quot;">​</a></h2><p>After moving to the position you want, first confirm that the coordinate system in the upper-right corner is the one you want. Then press the <code>Point</code> button on the robot arm or drag in a <code>Point</code> node in the software to record the current coordinate position.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><h3 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to &quot;Concept&quot;">​</a></h3><p><code>Vision</code> has two main types:</p><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;">Positioning</th><th style="text-align:center;">Inspection</th></tr></thead><tbody><tr><td style="text-align:center;">Editable tasks</td><td style="text-align:center;">Object positioning, TM Landmark positioning, servo positioning,<br>object calibration, Smart-Pick</td><td style="text-align:center;">AOI recognition and visual I/O triggering</td></tr><tr><td style="text-align:center;">Creates a new coordinate system</td><td style="text-align:center;">Yes</td><td style="text-align:center;">No</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Note</p><p>A <code>Vision</code> (Positioning) task also has a <code>Point</code> function. In other words, it moves to the specified position before starting visual recognition. Before creating <code>Vision</code>, check that the coordinate system is correct, usually Robot Base.</p></div><h3 id="how-to-use-it" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h3><p>In the basic course, we mainly use <strong>object positioning</strong> and <strong>Landmark</strong> to introduce <code>Vision</code>.</p><p>Whether it is object positioning or Landmark, both use a <code>Vision</code> node under <code>Positioning</code>. Move the arm to a suitable position first, then drag in a <code>Vision</code> node. After adding it, click the upper-left edit control to enter the editing screen. Click <code>Select</code> next to <code>Vision Task</code>, then click <img src="'+t+'" alt="Create vision task icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> to create a new vision task. Give it any name, then enter the vision task editor. Confirm that <code>Eye-in-Hand</code> is selected on the left and click <code>Set</code>, then follow the steps below to set up object positioning or Landmark.</p><h4 id="object-positioning" tabindex="-1">Object Positioning <a class="header-anchor" href="#object-positioning" aria-label="Permalink to &quot;Object Positioning&quot;">​</a></h4><p>Click <code>Object Positioning</code> → <code>Next</code>. After it finishes running, you will enter the object positioning editing flow. The blocks on the left are the recognition flow. Set them one by one in order; it is not hard to remember.</p><p>In the first block (<code>Motion</code>), click <code>Set Working Plane</code> → <code>Create</code> → <code>Yes</code> to enter the working plane setup. On the <code>Vision Application Selection</code> page, choose <code>Auto</code> → <code>Next</code>. You should see the current camera view in the center. Put the <strong>calibration board</strong> where the camera can clearly detect it. It is recommended to place two or three <strong>mahjong blocks</strong> underneath so the <strong>calibration board</strong> stays level. Then click <img src="'+i+'" alt="Adjust camera parameters icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> → <code>Yes</code> to enable lighting during calibration. Press <code>Next</code>, then follow the prompt and hold <code>PLAY</code> on the controller. The arm will run automatic calibration. When the progress bar is full and the prompt disappears, a &quot;calibration complete&quot; window appears. Click <code>OK</code>, give the working plane any name, then click <code>Save</code> → <code>OK</code>. After this step, you can remove the <strong>calibration board</strong>.</p><p>Next, click the <code>Camera</code> block on the right. It is recommended to check <code>Built-in Light</code>; it turns on the light during vision tasks and turns it off after recognition, which reduces failures caused by the environment. Click <code>Auto Adjust Camera Parameters</code> to finish this step.</p><p>When the <code>Camera</code> block is selected, a <img src="'+t+'" alt="Add flow node icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> appears below it. Click it, find <code>Pattern Matching (Contour Feature)</code> under <code>Find</code>, select it, and click <code>OK</code>. Put <strong>one mahjong block</strong> in the image, preferably straight, so selecting the template is easier. Choose <code>Select Template</code> on the right. In the template selection window, drag a rectangle around the <strong>TM</strong> logo on the <strong>mahjong block</strong>. Avoid the small text below and the QR Code above. Click <code>Next</code>, wait for it to finish, then choose the template you think is most accurate and click <code>OK</code>. Important: after creating the vision task and before actually picking it up, do not move the mahjong block, or you will need to recreate the task.</p><p>Click <img src="'+o+'" alt="Save icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> in the upper-left corner → <code>Save</code> → <code>Yes</code> to save the vision task. Finally click <code>Yes</code> → <code>Set</code> → <code>Confirm</code> to leave the vision task setup page. Done.</p><h4 id="landmark" tabindex="-1">Landmark <a class="header-anchor" href="#landmark" aria-label="Permalink to &quot;Landmark&quot;">​</a></h4><p>Click <code>Landmark Positioning</code> → <code>Next</code>. After it finishes running, you will enter the Landmark recognition editing flow. Like object positioning, the blocks on the left are the recognition flow, but Landmark is much easier to set up.</p><p>Unlike object positioning, the first step does not require setting the <code>Motion</code> block, because Landmark detects automatically. Click the <code>Camera</code> block on the left, check <code>Built-in Light</code> (recommended), and click <code>Auto Adjust Camera Parameters</code>. Then click the final <code>SUMMARY</code> block. After confirming that a box appears around the Landmark, click <img src="'+o+'" alt="Save icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> → <code>Save</code> → <code>Yes</code> to save the task. Finally click <code>Yes</code> → <code>Set</code> → <code>Confirm</code> to leave the setup page. Done.</p><h3 id="case-when-recognition-fails" tabindex="-1">Case When Recognition Fails <a class="header-anchor" href="#case-when-recognition-fails" aria-label="Permalink to &quot;Case When Recognition Fails&quot;">​</a></h3><p>After a vision task is created, the node has two branches below it: <code>Found</code> and <code>Miss</code>. They mean &quot;object detected&quot; and &quot;recognition failed.&quot; The success case is easy: continue writing what to do next. For failure, the most common approach is to keep recognizing until it succeeds.</p><p>Use a <code>Goto</code> node. Select the <code>Vision</code> node, drag in <code>Goto</code>, and choose <code>Lost Path</code>; this connects <code>Goto</code> under the <code>Miss</code> branch. Then click the pencil on <code>Goto</code>, click <code>Set Goto Target</code>, and the screen turns gray with all nodes highlighted. Click the <code>Vision</code> node → <code>Confirm</code>, and <code>Goto</code> will loop back to <code>Vision</code>. After that, if recognition fails, it keeps trying until it finds the target.</p><div class="tip custom-block"><p class="custom-block-title">Small Tip</p><p>As mentioned earlier, <code>Vision</code> creates a new coordinate system. After creating <code>Vision</code>, set <code>Point</code> to use <code>Vision Base</code>, and you can accurately control the arm to pick up or place the mahjong block.</p></div><h2 id="set" tabindex="-1">Set <a class="header-anchor" href="#set" aria-label="Permalink to &quot;Set&quot;">​</a></h2><p><code>Set</code> is powerful, but this chapter only explains how to use it to open and close the gripper.</p><h3 id="create" tabindex="-1">Create <a class="header-anchor" href="#create" aria-label="Permalink to &quot;Create&quot;">​</a></h3><p>You can drag <code>Set</code> from the left side of the software, or create it with the <code>SET</code> button on the robot arm. Competitions may lock the button method.</p><h3 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;Configure&quot;">​</a></h3><p>To control the gripper, enter the <code>Digital Output</code> setting in <code>Set</code>, click <code>Select</code> on the right, and find <code>DO_0</code> under the end module in the window that appears. This controls the gripper state.</p><p>There is a circle next to <code>DO_0</code>. Clicking it cycles through <code>H</code>, <code>L</code>, and blank. <code>H</code> means <strong>grip</strong>, and <code>L</code> means <strong>release</strong>. Pretty intuitive.</p><p>Click <code>Output Test</code> to move the gripper to the state you set.</p><h2 id="wait-for" tabindex="-1">Wait for <a class="header-anchor" href="#wait-for" aria-label="Permalink to &quot;Wait for&quot;">​</a></h2><p><code>Wait for</code> can wait for I/O, time, variables, and other conditions, but this chapter only covers the most common use: waiting for time.</p><h3 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>In basic projects, it is often used after opening or closing the gripper. Gripping and releasing take time. If the project speed is high, the gripper may miss or toss the object because things move too quickly. To make sure the gripper finishes before the next action, add a <code>Wait for</code> after the gripper action.</p><h3 id="how-to-use-it-1" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h3><p>In the <code>Wait for</code> editor, choose <code>Select</code> next to <code>Time</code>. In the window on the right, choose the top option with an input box, usually the default, and enter the wait time. A common suggestion is <code>500</code>, meaning 500 ms, or 0.5 seconds.</p><h2 id="move" tabindex="-1">Move <a class="header-anchor" href="#move" aria-label="Permalink to &quot;Move&quot;">​</a></h2><h3 id="purpose-1" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-1" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>After operating the gripper, we often use <code>Move</code> to raise the arm before moving to the next point, so it does not hit anything along the path.</p><h3 id="how-to-use-it-2" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h3><p>Usually we use the tool coordinate system for movement. Enter a negative value on the <code>Z</code> axis to move upward, such as <code>-100</code>, meaning up 100 mm, or 10 cm.</p><h2 id="stop" tabindex="-1">Stop <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;Stop&quot;">​</a></h2><p><code>Stop</code> is an ending node. It goes at the end of a project and automatically exits the project execution screen when reached. Since <code>Stop</code> represents the end, no node can be connected under it. It is not mandatory, but it is a good habit to put <code>Stop</code> at the end of every project.</p><h2 id="running-a-project" tabindex="-1">Running a Project <a class="header-anchor" href="#running-a-project" aria-label="Permalink to &quot;Running a Project&quot;">​</a></h2><h3 id="start-running" tabindex="-1">Start Running <a class="header-anchor" href="#start-running" aria-label="Permalink to &quot;Start Running&quot;">​</a></h3><p>Press <code>PLAY</code> on the controller. The screen enters the project execution page, plays three beeps, and then starts running.</p><h3 id="control-speed" tabindex="-1">Control Speed <a class="header-anchor" href="#control-speed" aria-label="Permalink to &quot;Control Speed&quot;">​</a></h3><p>The row of lights under the controller shows the current project speed. The default is <code>5%</code>. Use <code>+</code> and <code>-</code> on the controller to change the speed. Beginners should usually keep it below <code>15%</code>, then raise the limit gradually after becoming familiar with the arm.</p><h3 id="return-to-the-controller" tabindex="-1">Return to the Controller <a class="header-anchor" href="#return-to-the-controller" aria-label="Permalink to &quot;Return to the Controller&quot;">​</a></h3><p>After execution finishes, if there is no <code>Stop</code> node, the software stays on the execution screen. Press <code>STOP</code> on the controller to return to the project editing screen.</p><p>Another case is when the project does not finish, whether because of an error or because it is stuck in an infinite loop, such as a wrong loop condition or a vision task that cannot find the target. In that case, you can also press <code>STOP</code> to stop and exit execution.</p><h2 id="common-errors" tabindex="-1">Common Errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common Errors&quot;">​</a></h2><h3 id="causes-and-signs" tabindex="-1">Causes and Signs <a class="header-anchor" href="#causes-and-signs" aria-label="Permalink to &quot;Causes and Signs&quot;">​</a></h3><p>The robot arm may report an error after hitting something, or when a joint is pulled to its limit, also called a singularity. The arm light turns red and the software becomes gray and cannot be operated.</p><h3 id="how-to-clear-it" tabindex="-1">How to Clear It <a class="header-anchor" href="#how-to-clear-it" aria-label="Permalink to &quot;How to Clear It&quot;">​</a></h3><ol><li>Hold <code>FREE</code> on the arm and move it away from the original position, obstacle, or singularity</li><li>Long-press <code>STOP</code> on the controller to clear the error state</li><li>Review and modify the project, confirm the cause, and fix it</li></ol><div class="warning custom-block"><p class="custom-block-title">Error as soon as it moves</p><p>If the arm reports an error as soon as it moves, but it can still move, one joint may be near a singularity, possibly because it has been rotated a full circle. Keep trying to identify that joint, manually correct it, and set the arm back to <strong>Standard Pose</strong> so it will not get stuck at that joint again.</p></div><div class="warning custom-block"><p class="custom-block-title">When the error cannot be cleared</p><p>You can try the most primitive and violent method: reboot.</p><p>But try not to rely on this. Learn to find and solve the problem. If you cannot clear an error during competition, it may be counted as an unfinished run.</p></div>',71)])])}const x=r(l,[["render",h]]);export{v as __pageData,x as default};
